{"command":"cat << 'EOF' > src/lz4_block.cpp
#include "lz4_block.h"
#include "xxhash.h"

int lz4_decompress_block(const uint8_t* src, size_t src_len,
                         uint8_t* dst, size_t dst_capacity,
                         const uint8_t* dict, size_t dict_len) {
    size_t ip = 0;
    size_t op = 0;

    while (ip < src_len) {
        uint8_t token = src[ip++];
        size_t lit_len = token >> 4;
        size_t match_len = token & 0x0F;

        if (lit_len == 15) {
            uint8_t s;
            do {
                if (ip >= src_len) return -1;
                s = src[ip++];
                lit_len += s;
            } while (s == 255);
        }

        if (ip + lit_len > src_len || op + lit_len > dst_capacity) return -1;
        std::memcpy(dst + op, src + ip, lit_len);
        ip += lit_len;
        op += lit_len;

        if (ip == src_len) {
            // End of block reached after literals
            break;
        }

        if (ip + 2 > src_len) return -1;
        uint16_t offset = src[ip] | ((uint16_t)src[ip + 1] << 8);
        ip += 2;
        if (offset == 0) return -1;

        if (match_len == 15) {
            uint8_t s;
            do {
                if (ip >= src_len) return -1;
                s = src[ip++];
                match_len += s;
            } while (s == 255);
        }
        match_len += 4;

        if (op + match_len > dst_capacity) return -1;

        if (offset <= op) {
            size_t ref = op - offset;
            for (size_t m = 0; m < match_len; ++m) {
                dst[op++] = dst[ref++];
            }
        } else {
            size_t dict_back = offset - op;
            if (dict_back > dict_len || dict == nullptr) return -1;
            size_t dict_ref = dict_len - dict_back;
            size_t copy_from_dict = std::min(match_len, dict_back);
            for (size_t m = 0; m < copy_from_dict; ++m) {
                dst[op++] = dict[dict_ref++];
            }
            size_t remaining = match_len - copy_from_dict;
            size_t ref = op - offset;
            for (size_t m = 0; m < remaining; ++m) {
                dst[op++] = dst[ref++];
            }
        }
    }
    return static_cast<int>(op);
}

static size_t compress_fast(const uint8_t* src, size_t src_len,
                           uint8_t* dst, size_t dst_capacity,
                           int acceleration) {
    if (src_len == 0) return 0;
    if (src_len < 13) {
        if (dst_capacity < src_len + 16) return 0;
        size_t lit_len = src_len;
        size_t op = 0;
        dst[op++] = static_cast<uint8_t>(std::min(lit_len, (size_t)15) << 4);
        if (lit_len >= 15) {
            size_t l_extra = lit_len - 15;
            while (l_extra >= 255) {
                dst[op++] = 255;
                l_extra -= 255;
            }
            dst[op++] = static_cast<uint8_t>(l_extra);
        }
        std::memcpy(dst + op, src, lit_len);
        op += lit_len;
        return op;
    }

    static const size_t HASH_SIZE = 65536;
    int32_t hash_table[HASH_SIZE];
    std::fill(hash_table, hash_table + HASH_SIZE, -1);

    auto hash4 = [](uint32_t v) -> uint32_t {
        return (v * 2654435761U) >> 16;
    };

    size_t ip = 0;
    size_t anchor = 0;
    size_t op = 0;
    size_t step = std::max(1, acceleration);

    while (ip + 12 <= src_len) {
        uint32_t val = read32le(src + ip);
        uint32_t h = hash4(val);
        int32_t ref = hash_table[h];
        hash_table[h] = static_cast<int32_t>(ip);

        if (ref != -1 && (ip - ref) <= 65535 && ref < static_cast<int32_t>(ip)) {
            if (std::memcmp(src + ref, src + ip, 4) == 0) {
                while (ip > anchor && ref > 0 && src[ip - 1] == src[ref - 1]) {
                    ip--;
                    ref--;
                }

                size_t m_len = 4;
                while (ip + m_len + 5 <= src_len && src[ref + m_len] == src[ip + m_len]) {
                    m_len++;
                }

                size_t lit_len = ip - anchor;
                size_t m_code = m_len - 4;

                if (op >= dst_capacity) return 0;
                dst[op++] = static_cast<uint8_t>((std::min(lit_len, (size_t)15) << 4) | std::min(m_code, (size_t)15));

                if (lit_len >= 15) {
                    size_t l_extra = lit_len - 15;
                    while (l_extra >= 255) {
                        if (op >= dst_capacity) return 0;
                        dst[op++] = 255;
                        l_extra -= 255;
                    }
                    if (op >= dst_capacity) return 0;
                    dst[op++] = static_cast<uint8_t>(l_extra);
                }

                if (op + lit_len + 2 > dst_capacity) return 0;
                std::memcpy(dst + op, src + anchor, lit_len);
                op += lit_len;

                uint16_t offset = static_cast<uint16_t>(ip - ref);
                dst[op++] = offset & 0xFF;
                dst[op++] = (offset >> 8) & 0xFF;

                if (m_code >= 15) {
                    size_t m_extra = m_code - 15;
                    while (m_extra >= 255) {
                        if (op >= dst_capacity) return 0;
                        dst[op++] = 255;
                        m_extra -= 255;
                    }
                    if (op >= dst_capacity) return 0;
                    dst[op++] = static_cast<uint8_t>(m_extra);
                }

                ip += m_len;
                anchor = ip;

                if (ip + 4 <= src_len) {
                    hash_table[hash4(read32le(src + ip - 2))] = static_cast<int32_t>(ip - 2);
                }
                continue;
            }
        }
        ip += step;
    }

    size_t lit_len = src_len - anchor;
    if (op >= dst_capacity) return 0;
    dst[op++] = static_cast<uint8_t>(std::min(lit_len, (size_t)15) << 4);

    if (lit_len >= 15) {
        size_t l_extra = lit_len - 15;
        while (l_extra >= 255) {
            if (op >= dst_capacity) return 0;
            dst[op++] = 255;
            l_extra -= 255;
        }
        if (op >= dst_capacity) return 0;
        dst[op++] = static_cast<uint8_t>(l_extra);
    }

    if (op + lit_len > dst_capacity) return 0;
    std::memcpy(dst + op, src + anchor, lit_len);
    op += lit_len;

    return op;
}

static size_t compress_hc(const uint8_t* src, size_t src_len,
                          uint8_t* dst, size_t dst_capacity,
                          int clevel) {
    if (src_len == 0) return 0;
    if (src_len < 13) {
        return compress_fast(src, src_len, dst, dst_capacity, 1);
    }

    static const size_t HASH_SIZE = 65536;
    int32_t head[HASH_SIZE];
    std::fill(head, head + HASH_SIZE, -1);
    std::vector<int32_t> chain(src_len, -1);

    auto hash4 = [](uint32_t v) -> uint32_t {
        return (v * 2654435761U) >> 16;
    };

    size_t ip = 0;
    size_t anchor = 0;
    size_t op = 0;
    int max_attempts = 1 << std::min(clevel, 12);

    while (ip + 12 <= src_len) {
        uint32_t val = read32le(src + ip);
        uint32_t h = hash4(val);
        int32_t match = head[h];
        chain[ip] = match;
        head[h] = static_cast<int32_t>(ip);

        size_t best_len = 0;
        int32_t best_match = -1;
        int attempts = max_attempts;

        while (match != -1 && (ip - match) <= 65535 && attempts-- > 0) {
            if (src[match + best_len] == src[ip + best_len] && std::memcmp(src + match, src + ip, 4) == 0) {
                size_t m_len = 4;
                while (ip + m_len + 5 <= src_len && src[match + m_len] == src[ip + m_len]) {
