                dst[op++] = static_cast<uint8_t>(l_extra);
            }

            if (op + lit_len + 2 > dst_capacity) return 0;
            std::memcpy(dst + op, src + anchor, lit_len);
            op += lit_len;

            uint16_t offset = static_cast<uint16_t>(ip - ref);
            dst[op++] = offset & 0xFF;
            dst[op++] = (offset >> 8) & 0xFF;

            if (m_code >= 15) {
                size_t m_extra = m_code - 15;
                while (m_extra >= 255) {
                    if (op >= dst_capacity) return 0;
                    dst[op++] = 255;
                    m_extra -= 255;
                }
                if (op >= dst_capacity) return 0;
                dst[op++] = static_cast<uint8_t>(m_extra);
            }

            // Insert skipped positions into hash table
            for (size_t k = 1; k < m_len && (ip + k + 4 <= src_len); ++k) {
                uint32_t val_k = read32le(src + ip + k);
                uint32_t h_k = hash4(val_k);
                chain[ip + k] = head[h_k];
                head[h_k] = static_cast<int32_t>(ip + k);
            }

            ip += m_len;
            anchor = ip;
            continue;
        }
        ip++;
    }

    size_t lit_len = src_len - anchor;
    if (op >= dst_capacity) return 0;
    dst[op++] = static_cast<uint8_t>(std::min(lit_len, (size_t)15) << 4);

    if (lit_len >= 15) {
        size_t l_extra = lit_len - 15;
        while (l_extra >= 255) {
            if (op >= dst_capacity) return 0;
            dst[op++] = 255;
            l_extra -= 255;
        }
        if (op >= dst_capacity) return 0;
        dst[op++] = static_cast<uint8_t>(l_extra);
    }

    if (op + lit_len > dst_capacity) return 0;
    std::memcpy(dst + op, src + anchor, lit_len);
    op += lit_len;

    return op;
}

size_t lz4_compress_block(const uint8_t* src, size_t src_len,
                          uint8_t* dst, size_t dst_capacity,
                          int clevel,
                          const uint8_t* dict, size_t dict_len,
                          bool favor_dec_speed) {
    (void)dict; (void)dict_len; (void)favor_dec_speed;
    if (clevel <= 2) {
        int accel = 1;
        if (clevel < 1) accel = 1 + (-clevel);
        return compress_fast(src, src_len, dst, dst_capacity, accel);
    } else {
        return compress_hc(src, src_len, dst, dst_capacity, clevel);
    }
}
