#include "lz4_frame.h"
#include "lz4_block.h"
#include "xxhash.h"

static size_t get_block_max_size(int id) {
    switch (id) {
        case 4: return 64 * 1024;
        case 5: return 256 * 1024;
        case 6: return 1024 * 1024;
        case 7: return 4096 * 1024;
        default: return 4096 * 1024;
    }
}

static void write32le(std::ostream& out, uint32_t val) {
    uint8_t buf[4];
    buf[0] = val & 0xFF;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = (val >> 16) & 0xFF;
    buf[3] = (val >> 24) & 0xFF;
    out.write(reinterpret_cast<char*>(buf), 4);
}

static void write64le(std::ostream& out, uint64_t val) {
    uint8_t buf[8];
    for (int i = 0; i < 8; ++i) {
        buf[i] = (val >> (i * 8)) & 0xFF;
    }
    out.write(reinterpret_cast<char*>(buf), 8);
}

static uint32_t read32le_stream(std::istream& in) {
    uint8_t buf[4] = {0};
    in.read(reinterpret_cast<char*>(buf), 4);
    return buf[0] | (static_cast<uint32_t>(buf[1]) << 8) |
           (static_cast<uint32_t>(buf[2]) << 16) | (static_cast<uint32_t>(buf[3]) << 24);
}

static uint64_t read64le_stream(std::istream& in) {
    uint8_t buf[8] = {0};
    in.read(reinterpret_cast<char*>(buf), 8);
    uint64_t val = 0;
    for (int i = 0; i < 8; ++i) {
        val |= (static_cast<uint64_t>(buf[i]) << (i * 8));
    }
    return val;
}

int lz4_compress_stream(std::istream& in, std::ostream& out, const FrameCompressOptions& opts,
                        uint64_t* out_read_bytes, uint64_t* out_written_bytes) {
    uint64_t total_read = 0;
    uint64_t total_written = 0;

    if (opts.legacy) {
        write32le(out, 0x184C2102);
        total_written += 4;
        size_t block_max = 8 * 1024 * 1024;
        std::vector<uint8_t> in_buf(block_max);
        std::vector<uint8_t> comp_buf(block_max + 65536);

        while (in) {
            in.read(reinterpret_cast<char*>(in_buf.data()), block_max);
            size_t n = static_cast<size_t>(in.gcount());
            if (n == 0) break;
            total_read += n;

            size_t c_size = lz4_compress_block(in_buf.data(), n, comp_buf.data(), comp_buf.size(), opts.clevel);
            if (c_size == 0 || c_size >= n) {
                // If legacy doesn't fit, store as is or error
                c_size = n;
                write32le(out, static_cast<uint32_t>(c_size));
                out.write(reinterpret_cast<const char*>(in_buf.data()), n);
            } else {
                write32le(out, static_cast<uint32_t>(c_size));
                out.write(reinterpret_cast<const char*>(comp_buf.data()), c_size);
            }
            total_written += 4 + c_size;
        }
        if (out_read_bytes) *out_read_bytes = total_read;
        if (out_written_bytes) *out_written_bytes = total_written;
        return 0;
    }

    // Read full input if content_size is needed, or process chunk by chunk
    std::vector<uint8_t> full_input;
    if (opts.content_size) {
        full_input.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
        total_read = full_input.size();
    }

    // Write Magic Number
    write32le(out, 0x184D2204);
    total_written += 4;

    // FLG & BD
    uint8_t flg = 0x40; // Version 01
    if (opts.block_independence) flg |= 0x20;
    if (opts.block_checksum) flg |= 0x10;
    if (opts.content_size) flg |= 0x08;
    if (opts.stream_checksum) flg |= 0x04;
    if (!opts.dict.empty()) flg |= 0x01;

    uint8_t bd = (opts.block_max_size_id & 7) << 4;

    std::vector<uint8_t> header_bytes;
    header_bytes.push_back(flg);
    header_bytes.push_back(bd);

    if (opts.content_size) {
        uint64_t sz = full_input.size();
        for (int i = 0; i < 8; ++i) {
            header_bytes.push_back((sz >> (i * 8)) & 0xFF);
        }
    }

    if (!opts.dict.empty()) {
        uint32_t dict_id = XXH32(opts.dict.data(), opts.dict.size(), 0);
        for (int i = 0; i < 4; ++i) {
            header_bytes.push_back((dict_id >> (i * 8)) & 0xFF);
        }
    }

    uint8_t hc = (XXH32(header_bytes.data(), header_bytes.size(), 0) >> 8) & 0xFF;

    out.write(reinterpret_cast<const char*>(header_bytes.data()), header_bytes.size());
    out.put(static_cast<char>(hc));
    total_written += header_bytes.size() + 1;

    size_t block_max = get_block_max_size(opts.block_max_size_id);
    std::vector<uint8_t> in_buf(block_max);
    std::vector<uint8_t> comp_buf(block_max + 65536);
    std::vector<uint8_t> history_buf;

    uint32_t stream_crc = 0;
    bool crc_init = false;

    auto process_chunk = [&](const uint8_t* chunk_data, size_t chunk_size) {
        if (opts.stream_checksum) {
            if (!crc_init) {
                stream_crc = XXH32(chunk_data, chunk_size, 0);
                crc_init = true;
            } else {
                // To maintain XXH32 over entire stream, accumulating full data is easiest, or incremental XXH32
            }
        }

        const uint8_t* dict_ptr = opts.dict.empty() ? nullptr : opts.dict.data();
        size_t dict_len = opts.dict.size();

        if (!opts.block_independence && !history_buf.empty()) {
            dict_ptr = history_buf.data();
            dict_len = history_buf.size();
        }

        size_t c_size = lz4_compress_block(chunk_data, chunk_size, comp_buf.data(), comp_buf.size(),
                                          opts.clevel, dict_ptr, dict_len, opts.favor_dec_speed);

        if (c_size == 0 || c_size >= chunk_size) {
            // Uncompressed block
            uint32_t bsize = static_cast<uint32_t>(chunk_size) | 0x80000000;
            write32le(out, bsize);
            out.write(reinterpret_cast<const char*>(chunk_data), chunk_size);
            total_written += 4 + chunk_size;

            if (opts.block_checksum) {
                uint32_t bcrc = XXH32(chunk_data, chunk_size, 0);
                write32le(out, bcrc);
                total_written += 4;
            }
        } else {
            // Compressed block
            uint32_t bsize = static_cast<uint32_t>(c_size);
            write32le(out, bsize);
            out.write(reinterpret_cast<const char*>(comp_buf.data()), c_size);
            total_written += 4 + c_size;

            if (opts.block_checksum) {
                uint32_t bcrc = XXH32(comp_buf.data(), c_size, 0);
                write32le(out, bcrc);
                total_written += 4;
            }
        }

        if (!opts.block_independence) {
            // Maintain up to 64KB history buffer
            size_t keep = std::min((size_t)65536, chunk_size);
            history_buf.assign(chunk_data + chunk_size - keep, chunk_data + chunk_size);
        }
    };

    if (opts.content_size) {
        size_t offset = 0;
        while (offset < full_input.size()) {
            size_t chunk_size = std::min(block_max, full_input.size() - offset);
            process_chunk(full_input.data() + offset, chunk_size);
            offset += chunk_size;
        }
        if (opts.stream_checksum) {
            stream_crc = XXH32(full_input.data(), full_input.size(), 0);
        }
    } else {
        std::vector<uint8_t> all_uncompressed;
        while (in) {
            in.read(reinterpret_cast<char*>(in_buf.data()), block_max);
            size_t n = static_cast<size_t>(in.gcount());
            if (n == 0) break;
            total_read += n;
            if (opts.stream_checksum) {
                all_uncompressed.insert(all_uncompressed.end(), in_buf.data(), in_buf.data() + n);
            }
            process_chunk(in_buf.data(), n);
        }
        if (opts.stream_checksum) {
            stream_crc = XXH32(all_uncompressed.data(), all_uncompressed.size(), 0);
        }
    }

    // End Mark
    write32le(out, 0);
    total_written += 4;

    // Content Checksum
    if (opts.stream_checksum) {
        write32le(out, stream_crc);
        total_written += 4;
    }

    if (out_read_bytes) *out_read_bytes = total_read;
    if (out_written_bytes) *out_written_bytes = total_written;
    return 0;
}

int lz4_decompress_stream(std::istream& in, std::ostream& out, const std::vector<uint8_t>& dict,
                          uint64_t* out_read_bytes, uint64_t* out_written_bytes) {
    uint64_t total_read = 0;
    uint64_t total_written = 0;

    while (in.peek() != EOF) {
        streamoff pos_start = in.tellg();
        uint32_t magic = read32le_stream(in);
        if (in.gcount() < 4) break;
        total_read += 4;

        if (magic == 0x184C2102) { // Legacy Frame
            size_t block_max = 8 * 1024 * 1024;
            std::vector<uint8_t> comp_buf;
            std::vector<uint8_t> decomp_buf(block_max);

            while (in) {
                uint32_t c_size = read32le_stream(in);
                if (in.gcount() < 4) break;
                total_read += 4;

                comp_buf.resize(c_size);
                in.read(reinterpret_cast<char*>(comp_buf.data()), c_size);
                if (in.gcount() < (streamsize)c_size) return 44;
                total_read += c_size;

                int d_size = lz4_decompress_block(comp_buf.data(), c_size, decomp_buf.data(), decomp_buf.size());
                if (d_size < 0) return 34;

                out.write(reinterpret_cast<const char*>(decomp_buf.data()), d_size);
                total_written += d_size;
            }
            continue;
        }

        if ((magic & 0xFFFFFFF0) == 0x184D2A50) { // Skippable Frame
            uint32_t skip_size = read32le_stream(in);
            total_read += 4;
            in.ignore(skip_size);
            total_read += skip_size;
            continue;
        }

        if (magic != 0x184D2204) {
            return 44; // Unrecognized header
        }

        uint8_t flg = in.get();
        uint8_t bd = in.get();
        total_read += 2;

        uint8_t ver = flg >> 6;
        if (ver != 1) return 44;

        bool block_indep = (flg & 0x20) != 0;
        bool block_checksum = (flg & 0x10) != 0;
        bool content_size_present = (flg & 0x08) != 0;
        bool stream_checksum = (flg & 0x04) != 0;
        bool dict_present = (flg & 0x01) != 0;

        int block_max_id = (bd >> 4) & 7;
        size_t block_max = get_block_max_size(block_max_id);

        std::vector<uint8_t> header_bytes;
        header_bytes.push_back(flg);
        header_bytes.push_back(bd);

        uint64_t content_size = 0;
        if (content_size_present) {
            content_size = read64le_stream(in);
            total_read += 8;
            for (int i = 0; i < 8; ++i) {
                header_bytes.push_back((content_size >> (i * 8)) & 0xFF);
            }
        }

        if (dict_present) {
            uint32_t dict_id = read32le_stream(in);
            total_read += 4;
            for (int i = 0; i < 4; ++i) {
                header_bytes.push_back((dict_id >> (i * 8)) & 0xFF);
            }
        }

        uint8_t hc = in.get();
        total_read += 1;

        uint8_t expected_hc = (XXH32(header_bytes.data(), header_bytes.size(), 0) >> 8) & 0xFF;
        if (hc != expected_hc) return 44;

        std::vector<uint8_t> comp_buf;
        std::vector<uint8_t> decomp_buf(block_max);
        std::vector<uint8_t> all_decompressed;
        std::vector<uint8_t> history_buf;

        while (true) {
            uint32_t bsize = read32le_stream(in);
            if (in.gcount() < 4) return 34;
            total_read += 4;

            if (bsize == 0) break; // End Mark

            bool uncompressed = (bsize & 0x80000000) != 0;
            size_t size = bsize & 0x7FFFFFFF;

            comp_buf.resize(size);
            in.read(reinterpret_cast<char*>(comp_buf.data()), size);
            if (in.gcount() < (streamsize)size) return 34;
            total_read += size;

            if (block_checksum) {
                uint32_t bcrc = read32le_stream(in);
                total_read += 4;
                if (XXH32(comp_buf.data(), size, 0) != bcrc) return 34;
            }

            if (uncompressed) {
                out.write(reinterpret_cast<const char*>(comp_buf.data()), size);
                total_written += size;
                if (stream_checksum) {
                    all_decompressed.insert(all_decompressed.end(), comp_buf.begin(), comp_buf.end());
                }
                if (!block_indep) {
                    size_t keep = std::min((size_t)65536, size);
                    history_buf.assign(comp_buf.end() - keep, comp_buf.end());
                }
            } else {
                const uint8_t* dict_ptr = dict.empty() ? nullptr : dict.data();
                size_t dict_len = dict.size();
                if (!block_indep && !history_buf.empty()) {
                    dict_ptr = history_buf.data();
                    dict_len = history_buf.size();
                }

                int d_size = lz4_decompress_block(comp_buf.data(), size, decomp_buf.data(), decomp_buf.size(),
                                                  dict_ptr, dict_len);
                if (d_size < 0) return 34;

                out.write(reinterpret_cast<const char*>(decomp_buf.data()), d_size);
                total_written += d_size;

                if (stream_checksum) {
                    all_decompressed.insert(all_decompressed.end(), decomp_buf.begin(), decomp_buf.begin() + d_size);
                }

                if (!block_indep) {
                    size_t keep = std::min((size_t)65536, (size_t)d_size);
                    history_buf.assign(decomp_buf.begin() + d_size - keep, decomp_buf.begin() + d_size);
                }
            }
        }

        if (stream_checksum) {
            uint32_t scrc = read32le_stream(in);
            total_read += 4;
            uint32_t calc_crc = XXH32(all_decompressed.data(), all_decompressed.size(), 0);
            if (scrc != calc_crc) return 34; // Content checksum error
        }
    }

    if (out_read_bytes) *out_read_bytes = total_read;
    if (out_written_bytes) *out_written_bytes = total_written;
    return 0;
}

int lz4_list_frames(std::istream& in, std::vector<FrameListInfo>& info_list) {
    while (in.peek() != EOF) {
        streamoff frame_pos_start = in.tellg();
        uint32_t magic = read32le_stream(in);
        if (in.gcount() < 4) break;

        FrameListInfo info;
        uint64_t frame_comp_size = 4;

        if (magic == 0x184C2102) { // Legacy Frame
            info.frame_type = 2; // Legacy
            info.block_max_size_id = 0;
            info.block_independence = false;
            info.block_checksum = false;
            info.stream_checksum = false;
            info.has_uncompressed_size = false;

            while (in) {
                uint32_t c_size = read32le_stream(in);
                if (in.gcount() < 4) break;
                frame_comp_size += 4;
                in.ignore(c_size);
                frame_comp_size += c_size;
            }
            info.compressed_size = frame_comp_size;
            info_list.push_back(info);
            continue;
        }

        if ((magic & 0xFFFFFFF0) == 0x184D2A50) { // Skippable
            info.frame_type = 3;
            uint32_t skip_size = read32le_stream(in);
            frame_comp_size += 4 + skip_size;
            in.ignore(skip_size);
            info.compressed_size = frame_comp_size;
            info_list.push_back(info);
            continue;
        }

        if (magic != 0x184D2204) {
            return 1; // Error
        }

        info.frame_type = 1;
        uint8_t flg = in.get();
        uint8_t bd = in.get();
        frame_comp_size += 2;

        info.block_independence = (flg & 0x20) != 0;
        info.block_checksum = (flg & 0x10) != 0;
        info.content_size_present = (flg & 0x08) != 0;
        info.stream_checksum = (flg & 0x04) != 0;
        bool dict_present = (flg & 0x01) != 0;

        info.block_max_size_id = (bd >> 4) & 7;

        if (info.content_size_present) {
