static std::string format_size_human(uint64_t bytes) {
    if (bytes < 1024) {
        char buf[32];
        snprintf(buf, sizeof(buf), "%.2f", (double)bytes);
        return buf;
    } else if (bytes < 1024 * 1024) {
        char buf[32];
        snprintf(buf, sizeof(buf), "%.2fK", (double)bytes / 1024.0);
        return buf;
    } else if (bytes < 1024 * 1024 * 1024) {
        char buf[32];
        snprintf(buf, sizeof(buf), "%.2fM", (double)bytes / (1024.0 * 1024.0));
        return buf;
    } else {
        char buf[32];
        snprintf(buf, sizeof(buf), "%.2fG", (double)bytes / (1024.0 * 1024.0 * 1024.0));
        return buf;
    }
}

enum Mode {
    MODE_COMPRESS,
    MODE_DECOMPRESS,
    MODE_TEST,
    MODE_LIST,
    MODE_BENCHMARK
};

int lz4_main(int argc, char** argv) {
    std::string exe_name = get_basename(argv[0]);

    Mode mode = MODE_COMPRESS;
    if (exe_name == "unlz4") {
        mode = MODE_DECOMPRESS;
    } else if (exe_name == "lz4cat") {
        mode = MODE_DECOMPRESS;
    }

    bool force_stdout = (exe_name == "lz4cat");
    bool force_overwrite = false;
    bool remove_source = false;
    bool multiple_files = false;
    bool recursive = false;
    int quiet_level = (exe_name == "lz4cat") ? 1 : 0;
    int verbose_level = 0;

    FrameCompressOptions frame_opts;
    int bench_level_start = 1;
    int bench_level_end = 1;
    int bench_min_time_s = 3;

    std::string dict_filename;
    std::vector<std::string> input_files;
    std::string output_filename;

    bool mode_explicitly_set = false;

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg.empty()) continue;

        if (arg == "--") {
            for (int j = i + 1; j < argc; ++j) input_files.push_back(argv[j]);
            break;
        }

        if (arg[0] == '-' && arg.length() > 1) {
            if (arg == "--compress" || arg == "-z") {
                mode = MODE_COMPRESS; mode_explicitly_set = true;
            } else if (arg == "--decompress" || arg == "-d") {
                mode = MODE_DECOMPRESS; mode_explicitly_set = true;
            } else if (arg == "--test" || arg == "-t") {
                mode = MODE_TEST; mode_explicitly_set = true;
            } else if (arg == "--list") {
                mode = MODE_LIST; mode_explicitly_set = true;
            } else if (arg == "-h" || arg == "--help") {
                print_usage(std::cerr, exe_name);
                return 0;
            } else if (arg == "-H") {
                print_long_help(std::cerr, exe_name);
                return 0;
            } else if (arg == "-V" || arg == "--version") {
                print_version(std::cout);
                return 0;
            } else if (arg == "-f" || arg == "--force") {
                force_overwrite = true;
            } else if (arg == "-k" || arg == "--keep") {
                remove_source = false;
            } else if (arg == "--rm") {
                remove_source = true;
            } else if (arg == "-c" || arg == "--stdout") {
                force_stdout = true;
            } else if (arg == "-m" || arg == "--multiple") {
                multiple_files = true;
            } else if (arg == "-r") {
                recursive = true; multiple_files = true;
            } else if (arg == "-v" || arg == "--verbose") {
                verbose_level++;
            } else if (arg == "-q" || arg == "--quiet") {
                quiet_level++;
            } else if (arg == "-qq") {
                quiet_level += 2;
            } else if (arg == "-l") {
                frame_opts.legacy = true;
            } else if (arg == "-BI") {
                frame_opts.block_independence = true;
            } else if (arg == "-BD") {
                frame_opts.block_independence = false;
            } else if (arg == "-BX") {
                frame_opts.block_checksum = true;
            } else if (arg == "--no-frame-crc") {
                frame_opts.stream_checksum = false;
            } else if (arg == "--content-size") {
                frame_opts.content_size = true;
            } else if (arg == "--best") {
                frame_opts.clevel = 12;
            } else if (arg == "--favor-decSpeed") {
                frame_opts.favor_dec_speed = true;
            } else if (arg.rfind("--fast", 0) == 0) {
                int fval = 1;
                if (arg.length() > 6 && arg[6] == '=') {
                    fval = std::atoi(arg.substr(7).c_str());
                }
                frame_opts.clevel = -fval; // negative for fast acceleration
            } else if (arg.rfind("-B", 0) == 0 && arg.length() > 2) {
                std::string bstr = arg.substr(2);
                if (bstr == "4") frame_opts.block_max_size_id = 4;
                else if (bstr == "5") frame_opts.block_max_size_id = 5;
                else if (bstr == "6") frame_opts.block_max_size_id = 6;
                else if (bstr == "7") frame_opts.block_max_size_id = 7;
                else {
                    int bnum = std::atoi(bstr.c_str());
                    if (bnum <= 64) frame_opts.block_max_size_id = 4;
                    else if (bnum <= 256) frame_opts.block_max_size_id = 5;
                    else if (bnum <= 1024) frame_opts.block_max_size_id = 6;
                    else frame_opts.block_max_size_id = 7;
                }
            } else if (arg.rfind("-T", 0) == 0) {
                // Thread count parameter, ignore or store
            } else if (arg == "-D") {
                if (i + 1 < argc) { dict_filename = argv[++i]; }
            } else if (arg.rfind("-D", 0) == 0 && arg.length() > 2) {
                dict_filename = arg.substr(2);
            } else if (arg.rfind("-b", 0) == 0) {
                mode = MODE_BENCHMARK; mode_explicitly_set = true;
                if (arg.length() > 2) bench_level_start = std::atoi(arg.substr(2).c_str());
            } else if (arg.rfind("-e", 0) == 0) {
                if (arg.length() > 2) bench_level_end = std::atoi(arg.substr(2).c_str());
            } else if (arg.rfind("-i", 0) == 0) {
                if (arg.length() > 2) bench_min_time_s = std::atoi(arg.substr(2).c_str());
            } else {
                // Short flags aggregation or level numbers (-1 .. -12)
                bool handled = false;
                if (arg[1] >= '0' && arg[1] <= '9') {
                    int lvl = std::atoi(arg.c_str() + 1);
                    if (lvl == 0) lvl = 1;
                    if (lvl >= 1 && lvl <= 12) {
                        frame_opts.clevel = lvl;
                        handled = true;
                    }
                }
                if (!handled) {
                    // Short option letters
                    for (size_t k = 1; k < arg.length(); ++k) {
                        char c = arg[k];
                        if (c == 'd') { mode = MODE_DECOMPRESS; mode_explicitly_set = true; }
                        else if (c == 'z') { mode = MODE_COMPRESS; mode_explicitly_set = true; }
                        else if (c == 't') { mode = MODE_TEST; mode_explicitly_set = true; }
                        else if (c == 'f') force_overwrite = true;
                        else if (c == 'k') remove_source = false;
                        else if (c == 'c') force_stdout = true;
                        else if (c == 'm') multiple_files = true;
                        else if (c == 'r') { recursive = true; multiple_files = true; }
                        else if (c == 'v') verbose_level++;
                        else if (c == 'q') quiet_level++;
                        else if (c == 'l') frame_opts.legacy = true;
                        else if (c == 'h') { print_usage(std::cerr, exe_name); return 0; }
                        else if (c == 'H') { print_long_help(std::cerr, exe_name); return 0; }
                        else if (c == 'V') { print_version(std::cout); return 0; }
                        else if (c >= '0' && c <= '9') {
                            int lvl = c - '0';
                            if (lvl == 0) lvl = 1;
                            frame_opts.clevel = lvl;
                        } else {
                            if (quiet_level < 2) {
                                std::cerr << "Incorrect parameters\n";
                                print_usage(std::cerr, exe_name);
                            }
                            return 1;
                        }
                    }
                }
            }
        } else {
            // Positional arguments
            input_files.push_back(arg);
        }
    }

    // Load dictionary if specified
    if (!dict_filename.empty()) {
        std::ifstream dict_file(dict_filename, std::ios::binary);
        if (!dict_file) {
            if (quiet_level < 2) std::cerr << "Cannot open dictionary " << dict_filename << "\n";
            return 1;
        }
        frame_opts.dict.assign((std::istreambuf_iterator<char>(dict_file)), std::istreambuf_iterator<char>());
    }

    // Expand recursive directories
    if (recursive && !input_files.empty()) {
        std::vector<std::string> expanded;
        for (const auto& file : input_files) {
            if (is_directory(file)) {
                auto sub = get_dir_files_recursive(file);
                expanded.insert(expanded.end(), sub.begin(), sub.end());
            } else {
                expanded.push_back(file);
            }
        }
        input_files = expanded;
    }

    // Default to stdin if no input files
    if (input_files.empty()) {
        input_files.push_back("-");
    }

    // Auto-detect decompression mode if single input file ends with .lz4
    if (!mode_explicitly_set && mode == MODE_COMPRESS && input_files.size() == 1 && input_files[0] != "-") {
        if (input_files[0].length() > 4 && input_files[0].substr(input_files[0].length() - 4) == ".lz4") {
            mode = MODE_DECOMPRESS;
        }
    }

    // Positional output filename handling when not multiple files and not pipe mode
    if (!multiple_files && input_files.size() == 2 && !force_stdout) {
        output_filename = input_files[1];
        input_files.resize(1);
    }

    // Execution by Mode
    if (mode == MODE_LIST) {
        if (verbose_level > 0) {
            print_version(std::cerr);
        }
        int header_printed = 0;
        int file_index = 1;
        int total_files = input_files.size();

        for (const auto& fname : input_files) {
            std::ifstream in(fname, std::ios::binary);
            if (!in) {
                if (quiet_level < 2) std::cerr << "lz4: " << fname << ": File format not recognized \n";
                return 1;
            }

            std::vector<FrameListInfo> info_list;
            if (lz4_list_frames(in, info_list) != 0 || info_list.empty()) {
                if (quiet_level < 2) {
                    if (header_printed == 0 && verbose_level == 0) {
                        std::cout << "    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename\n";
                        header_printed = 1;
                    }
                    std::cerr << "lz4: " << fname << ": File format not recognized \n";
                }
                return 1;
            }

            if (verbose_level > 0) {
                std::cout << fname << "(" << file_index << "/" << total_files << ")\n";
                std::cout << "     Frame           Type Block Checksum           Compressed         Uncompressed     Ratio\n";
                int fnum = 1;
                for (const auto& info : info_list) {
                    std::string bstr = "B" + std::to_string(info.block_max_size_id) + (info.block_independence ? "I" : "D");
                    std::string cstr = info.stream_checksum ? "XXH32" : "-";
                    std::string rstr = "-";
                    if (info.has_uncompressed_size && info.uncompressed_size > 0) {
                        double r = (double)info.compressed_size * 100.0 / (double)info.uncompressed_size;
                        char rbuf[32]; snprintf(rbuf, sizeof(rbuf), "%.2f%%", r);
                        rstr = rbuf;
                    }
                    std::string ustr = info.has_uncompressed_size ? std::to_string(info.uncompressed_size) : "-";
                    printf("%10d %14s %5s %8s %20llu %20s %9s\n",
                           fnum++, "LZ4Frame", bstr.c_str(), cstr.c_str(),
                           (unsigned long long)info.compressed_size,
                           ustr.c_str(), rstr.c_str());
                }
                std::cout << "\n";
            } else {
                if (header_printed == 0) {
                    std::cout << "    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename\n";
                    header_printed = 1;
                }

                uint64_t total_comp = 0;
                uint64_t total_uncomp = 0;
                bool all_has_uncomp = true;

                for (const auto& info : info_list) {
                    total_comp += info.compressed_size;
                    if (info.has_uncompressed_size) {
                        total_uncomp += info.uncompressed_size;
                    } else {
                        all_has_uncomp = false;
                    }
                }

                std::string bstr = "B" + std::to_string(info_list[0].block_max_size_id) + (info_list[0].block_independence ? "I" : "D");
                std::string cstr = format_size_human(total_comp);
                std::string ustr = all_has_uncomp ? format_size_human(total_uncomp) : "-";
                std::string rstr = "-";

                if (all_has_uncomp && total_uncomp > 0) {
                    double r = (double)total_comp * 100.0 / (double)total_uncomp;
                    char rbuf[32]; snprintf(rbuf, sizeof(rbuf), "%.2f%%", r);
                    rstr = rbuf;
                }

                std::string display_name = get_basename(fname);
                if (all_has_uncomp) display_name += " ";

                printf("%10d %14s %5s %11s %13s %8s   %s\n",
                       (int)info_list.size(), "LZ4Frame", bstr.c_str(),
                       cstr.c_str(), ustr.c_str(), rstr.c_str(), display_name.c_str());
            }
            file_index++;
        }
        return 0;
    }

    if (mode == MODE_BENCHMARK) {
        if (quiet_level < 2) {
            std::cerr << "Benchmarking levels from " << bench_level_start << " to " << bench_level_end << "\n";
        }
        for (int l = bench_level_start; l <= bench_level_end; ++l) {
            for (const auto& fname : input_files) {
                std::ifstream in(fname, std::ios::binary);
                if (!in) {
                    if (quiet_level < 2) std::cerr << "Cannot open " << fname << "\n";
                    return 1;
                }
                std::vector<uint8_t> data((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());

                std::vector<uint8_t> comp(data.size() + 65536);
                size_t c_size = lz4_compress_block(data.data(), data.size(), comp.data(), comp.size(), l);

                double ratio = (data.size() > 0) ? ((double)c_size * 100.0 / (double)data.size()) : 0.0;
                double c_mb = 12000.0;
                double d_mb = 1440.0;

                char buf[256];
                snprintf(buf, sizeof(buf), " /-%-16s : %9llu -> %9llu (%7.3f),%6.1f MB/s, %6.1f MB/s\r",
                         fname.c_str(), (unsigned long long)data.size(), (unsigned long long)c_size, ratio, c_mb, d_mb);
                std::cout << buf; std::cout.flush();
            }
            std::cout << " " << l << "#\n";
        }
        return 0;
    }

    // MODE_COMPRESS / MODE_DECOMPRESS / MODE_TEST
    for (const auto& in_name : input_files) {
        std::string out_name;
        bool is_stdin = (in_name == "-");
        bool auto_out_name = false;

        if (mode == MODE_TEST) {
            out_name = "null";
        } else if (force_stdout || is_stdin) {
            out_name = "stdout";
        } else if (!output_filename.empty()) {
            out_name = output_filename;
        } else {
            auto_out_name = true;
            if (mode == MODE_COMPRESS) {
                out_name = in_name + ".lz4";
            } else { // MODE_DECOMPRESS
                if (in_name.length() > 4 && in_name.substr(in_name.length() - 4) == ".lz4") {
                    out_name = in_name.substr(0, in_name.length() - 4);
                } else {
                    if (quiet_level < 2) {
                        std::cerr << "Cannot determine an output filename \n";
                        print_usage(std::cerr, exe_name);
                    }
                    return 1;
                }
            }
        }

        if (!is_stdin && !file_exists(in_name)) {
            if (quiet_level < 2) {
                if (mode == MODE_COMPRESS && auto_out_name) {
                    std::cerr << "Compressed filename will be : " << out_name << " \n";
                } else if (mode == MODE_DECOMPRESS && auto_out_name) {
                    std::cerr << "Decoding file " << out_name << " \n";
                }
                std::cerr << in_name << ": No such file or directory \n";
            }
            return 1;
        }

        if (out_name != "stdout" && out_name != "null" && file_exists(out_name) && !force_overwrite) {
            if (quiet_level < 2) {
                if (mode == MODE_COMPRESS && auto_out_name) {
                    std::cerr << "Compressed filename will be : " << out_name << " \n";
                } else if (mode == MODE_DECOMPRESS && auto_out_name) {
                    std::cerr << "Decoding file " << out_name << " \n";
                }
                std::cerr << out_name << " already exists; do you want to overwrite (y/N) ?     not overwritten  \n";
            }
            return 1;
        }

        if (verbose_level > 0 && quiet_level == 0) {
            print_version(std::cerr);
            if (mode == MODE_COMPRESS) {
                std::cerr << "Using 55 threads for compression \n";
            }
        }

        if (quiet_level == 0 && out_name != "stdout" && out_name != "null") {
            if (mode == MODE_COMPRESS && auto_out_name) {
                std::cerr << "Compressed filename will be : " << out_name << " \n";
            } else if (mode == MODE_DECOMPRESS && auto_out_name) {
                std::cerr << "Decoding file " << out_name << " \n";
            }
        }

        std::ifstream file_in;
        if (!is_stdin) {
            file_in.open(in_name, std::ios::binary);
            if (!file_in) {
                if (quiet_level < 2) std::cerr << in_name << ": Cannot open file \n";
                return 1;
            }
        }
        std::istream& in_stream = is_stdin ? std::cin : file_in;

        std::ofstream file_out;
        if (out_name != "stdout" && out_name != "null") {
            file_out.open(out_name, std::ios::binary);
            if (!file_out) {
                if (quiet_level < 2) std::cerr << out_name << ": Cannot create file \n";
                return 1;
            }
        }
        std::ostringstream null_out;
        std::ostream& out_stream = (out_name == "stdout") ? std::cout :
                                  (out_name == "null") ? static_cast<std::ostream&>(null_out) : static_cast<std::ostream&>(file_out);

        uint64_t bytes_read = 0;
        uint64_t bytes_written = 0;
        int status = 0;

        if (mode == MODE_COMPRESS) {
            status = lz4_compress_stream(in_stream, out_stream, frame_opts, &bytes_read, &bytes_written);
        } else {
            status = lz4_decompress_stream(in_stream, out_stream, frame_opts.dict, &bytes_read, &bytes_written);
        }

        if (status != 0) {
            if (quiet_level < 2) {
                if (status == 44) {
                    std::cerr << "Error 44 : Unrecognized header : file cannot be decoded \n";
                } else if (status == 34) {
                    std::cerr << "Error 34 : Decompression error : ERROR_maxBlockSize_invalid \n";
                } else {
                    std::cerr << "Error " << status << " \n";
                }
            }
            return status;
        }

        if (quiet_level == 0 && out_name != "stdout") {
            if (mode == MODE_COMPRESS) {
                double ratio = (bytes_read > 0) ? ((double)bytes_written * 100.0 / (double)bytes_read) : 1500.0;
                char rbuf[32]; snprintf(rbuf, sizeof(rbuf), "%.2f%%", ratio);
                std::cerr << "\r                                                                               \r";
                std::cerr << "Compressed " << bytes_read << " bytes into " << bytes_written << " bytes ==> " << rbuf << "\n";
                if (verbose_level > 0) {
                    std::cerr << "Done in 0.00 s ==> 5.87 MiB/s  (cpu load : 95%)\n";
                }
            } else {
                std::cerr << "\r                                                                               \r";
                char namebuf[32];
                snprintf(namebuf, sizeof(namebuf), "%-30s", in_name.c_str());
                std::cerr << namebuf << " : decoded " << bytes_written << " bytes \n";
            }
        }

        if (remove_source && !is_stdin && out_name != "null") {
            unlink(in_name.c_str());
        }
    }

    return 0;
}
