static const char* LZ4_VERSION = "v1.10.0";
static const char* LZ4_AUTHOR = "Yann Collet";

static std::string get_basename(const std::string& path) {
    size_t pos = path.find_last_of("/\\");
    if (pos == std::string::npos) return path;
    return path.substr(pos + 1);
}

static bool file_exists(const std::string& path) {
    struct stat st;
    return (stat(path.c_str(), &st) == 0);
}

static bool is_directory(const std::string& path) {
    struct stat st;
    if (stat(path.c_str(), &st) != 0) return false;
    return S_ISDIR(st.st_mode);
}

static std::vector<std::string> get_dir_files_recursive(const std::string& dir_path) {
    std::vector<std::string> results;
    DIR* dir = opendir(dir_path.c_str());
    if (!dir) return results;

    struct dirent* entry;
    while ((entry = readdir(dir)) != nullptr) {
        std::string name = entry->d_name;
        if (name == "." || name == "..") continue;
        std::string full_path = dir_path + "/" + name;
        if (is_directory(full_path)) {
            auto sub = get_dir_files_recursive(full_path);
            results.insert(results.end(), sub.begin(), sub.end());
        } else {
            results.push_back(full_path);
        }
    }
    closedir(dir);
    return results;
}

static void print_version(std::ostream& out) {
    out << "*** lz4 " << LZ4_VERSION << " 64-bit multithread, by " << LZ4_AUTHOR << " ***\n";
}

static void print_usage(std::ostream& out, const std::string& exe_name) {
    print_version(out);
    out << "Usage : \n";
    out << "      " << exe_name << " [arg] [input] [output] \n\n";
    out << "input   : a filename \n";
    out << "          with no FILE, or when FILE is - or stdin, read standard input\n";
    out << "Arguments : \n";
    out << " -1     : fast compression (default) \n";
    out << " -12    : slowest compression level \n";
    out << " -T#    : use # threads for compression (default:0==auto) \n";
    out << " -d     : decompression (default for .lz4 extension)\n";
    out << " -f     : overwrite output without prompting \n";
    out << " -k     : preserve source files(s)  (default) \n";
    out << "--rm    : remove source file(s) after successful de/compression \n";
    out << " -h/-H  : display help/long help and exit \n\n";
    out << "Advanced arguments :\n";
    out << " -V     : display Version number and exit \n";
    out << " -v     : verbose mode \n";
    out << " -q     : suppress warnings; specify twice to suppress errors too\n";
    out << " -c     : force write to standard output, even if it is the console\n";
    out << " -t     : test compressed file integrity\n";
    out << " -m     : multiple input files (implies automatic output filenames)\n";
    out << " -r     : operate recursively on directories (sets also -m) \n";
    out << " -l     : compress using Legacy format (Linux kernel compression)\n";
    out << " -z     : force compression \n";
    out << " -D FILE: use FILE as dictionary (compression & decompression)\n";
    out << " -B#    : cut file into blocks of size # bytes [32+]\n";
    out << "                     or predefined block size [4-7] (default: 7) \n";
    out << " -BI    : Block Independence (default) \n";
    out << " -BD    : Block dependency (improves compression ratio) \n";
    out << " -BX    : enable block checksum (default:disabled) \n";
    out << "--no-frame-crc : disable stream checksum (default:enabled) \n";
    out << "--content-size : compressed frame includes original size (default:not present)\n";
    out << "--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)\n";
    out << "--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)\n";
