        if (magic != 0x184D2204) {
            return 44;
        }

        uint8_t flg = in.get();
        uint8_t bd = in.get();
        total_read += 2;

        uint8_t ver = flg >> 6;
        if (ver != 1) return 44;

        bool block_indep = (flg & 0x20) != 0;
        bool block_checksum = (flg & 0x10) != 0;
        bool content_size_present = (flg & 0x08) != 0;
        bool stream_checksum = (flg & 0x04) != 0;
        bool dict_present = (flg & 0x01) != 0;

        int block_max_id = (bd >> 4) & 7;
        size_t block_max = get_block_max_size(block_max_id);

        std::vector<uint8_t> header_bytes;
        header_bytes.push_back(flg);
        header_bytes.push_back(bd);

        uint64_t content_size = 0;
        if (content_size_present) {
            content_size = read64le_stream(in);
            total_read += 8;
            for (int i = 0; i < 8; ++i) {
                header_bytes.push_back((content_size >> (i * 8)) & 0xFF);
            }
        }

        if (dict_present) {
            uint32_t dict_id = read32le_stream(in);
            total_read += 4;
            for (int i = 0; i < 4; ++i) {
                header_bytes.push_back((dict_id >> (i * 8)) & 0xFF);
            }
        }

        uint8_t hc = in.get();
        total_read += 1;

        uint8_t expected_hc = (XXH32(header_bytes.data(), header_bytes.size(), 0) >> 8) & 0xFF;
        if (hc != expected_hc) return 44;

        std::vector<uint8_t> comp_buf;
        std::vector<uint8_t> decomp_buf(block_max);
        std::vector<uint8_t> all_decompressed;
        std::vector<uint8_t> history_buf;

        while (true) {
            uint32_t bsize = read32le_stream(in);
            if (in.gcount() < 4) return 34;
            total_read += 4;

            if (bsize == 0) break;

            bool uncompressed = (bsize & 0x80000000) != 0;
            size_t size = bsize & 0x7FFFFFFF;

            comp_buf.resize(size);
            in.read(reinterpret_cast<char*>(comp_buf.data()), size);
            if (static_cast<size_t>(in.gcount()) < size) return 34;
            total_read += size;

            if (block_checksum) {
                uint32_t bcrc = read32le_stream(in);
                total_read += 4;
                if (XXH32(comp_buf.data(), size, 0) != bcrc) return 34;
            }

