                out.write(reinterpret_cast<const char*>(comp_buf.data()), size);
                total_written += size;
                if (stream_checksum) {
                    all_decompressed.insert(all_decompressed.end(), comp_buf.begin(), comp_buf.end());
                }
                if (!block_indep) {
                    size_t keep = std::min((size_t)65536, size);
                    history_buf.assign(comp_buf.end() - keep, comp_buf.end());
                }
            } else {
                const uint8_t* dict_ptr = dict.empty() ? nullptr : dict.data();
                size_t dict_len = dict.size();
                if (!block_indep && !history_buf.empty()) {
                    dict_ptr = history_buf.data();
                    dict_len = history_buf.size();
                }

                int d_size = lz4_decompress_block(comp_buf.data(), size, decomp_buf.data(), decomp_buf.size(),
                                                  dict_ptr, dict_len);
                if (d_size < 0) return 34;

                out.write(reinterpret_cast<const char*>(decomp_buf.data()), d_size);
                total_written += d_size;

                if (stream_checksum) {
                    all_decompressed.insert(all_decompressed.end(), decomp_buf.begin(), decomp_buf.begin() + d_size);
                }

                if (!block_indep) {
                    size_t keep = std::min((size_t)65536, (size_t)d_size);
                    history_buf.assign(decomp_buf.begin() + d_size - keep, decomp_buf.begin() + d_size);
