static std::string format_size_human(uint64_t bytes) {
    if (bytes < 1024) {
        char buf[32];
        snprintf(buf, sizeof(buf), "%.2f", (double)bytes);
        return buf;
    } else if (bytes < 1024 * 1024) {
        char buf[32];
        snprintf(buf, sizeof(buf), "%.2fK", (double)bytes / 1024.0);
        return buf;
    } else if (bytes < 1024 * 1024 * 1024) {
        char buf[32];
        snprintf(buf, sizeof(buf), "%.2fM", (double)bytes / (1024.0 * 1024.0));
        return buf;
    } else {
        char buf[32];
        snprintf(buf, sizeof(buf), "%.2fG", (double)bytes / (1024.0 * 1024.0 * 1024.0));
        return buf;
    }
}

