        input_files.push_back("-");
    }

    if (!mode_explicitly_set && mode == MODE_COMPRESS && input_files.size() == 1 && input_files[0] != "-") {
        if (input_files[0].length() > 4 && input_files[0].substr(input_files[0].length() - 4) == ".lz4") {
            mode = MODE_DECOMPRESS;
        }
    }

    // Positional output filename handling only for single-input compress/decompress
    if ((mode == MODE_COMPRESS || mode == MODE_DECOMPRESS) && !multiple_files && input_files.size() == 2 && !force_stdout) {
        output_filename = input_files[1];
        input_files.resize(1);
    }

    if (mode == MODE_LIST) {
        if (verbose_level > 0) {
            print_version(std::cerr);
        }
        int header_printed = 0;
        int file_index = 1;
        int total_files = input_files.size();

        for (const auto& fname : input_files) {
            std::ifstream in(fname, std::ios::binary);
            if (!in) {
                if (quiet_level < 2) std::cerr << "lz4: " << fname << ": File format not recognized \n";
                return 1;
            }

            std::vector<FrameListInfo> info_list;
            if (lz4_list_frames(in, info_list) != 0 || info_list.empty()) {
                if (quiet_level < 2) {
                    if (header_printed == 0 && verbose_level == 0) {
                        std::cout << "    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename\n";
                        header_printed = 1;
                    }
                    std::cerr << "lz4: " << fname << ": File format not recognized \n";
                }
                return 1;
            }

            if (verbose_level > 0) {
                std::cout << fname << "(" << file_index << "/" << total_files << ")\n";
                std::cout << "     Frame           Type Block Checksum           Compressed         Uncompressed     Ratio\n";
                int fnum = 1;
                for (const auto& info : info_list) {
                    std::string bstr = "B" + std::to_string(info.block_max_size_id) + (info.block_independence ? "I" : "D");
                    std::string cstr = info.stream_checksum ? "XXH32" : "-";
                    std::string rstr = "-";
                    if (info.has_uncompressed_size && info.uncompressed_size > 0) {
                        double r = (double)info.compressed_size * 100.0 / (double)info.uncompressed_size;
                        char rbuf[32]; snprintf(rbuf, sizeof(rbuf), "%.2f%%", r);
                        rstr = rbuf;
                    }
                    std::string ustr = info.has_uncompressed_size ? std::to_string(info.uncompressed_size) : "-";
                    printf("%10d %14s %5s %8s %20llu %20s %9s\n",
                           fnum++, "LZ4Frame", bstr.c_str(), cstr.c_str(),
                           (unsigned long long)info.compressed_size,
                           ustr.c_str(), rstr.c_str());
                }
                std::cout << "\n";
            } else {
                if (header_printed == 0) {
                    std::cout << "    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename\n";
                    header_printed = 1;
                }

                uint64_t total_comp = 0;
                uint64_t total_uncomp = 0;
                bool all_has_uncomp = true;

                for (const auto& info : info_list) {
                    total_comp += info.compressed_size;
                    if (info.has_uncompressed_size) {
                        total_uncomp += info.uncompressed_size;
                    } else {
                        all_has_uncomp = false;
                    }
                }

                std::string bstr = "B" + std::to_string(info_list[0].block_max_size_id) + (info_list[0].block_independence ? "I" : "D");
                std::string cstr = format_size_human(total_comp);
                std::string ustr = all_has_uncomp ? format_size_human(total_uncomp) : "-";
                std::string rstr = "-";

                if (all_has_uncomp && total_uncomp > 0) {
                    double r = (double)total_comp * 100.0 / (double)total_uncomp;
                    char rbuf[32]; snprintf(rbuf, sizeof(rbuf), "%.2f%%", r);
                    rstr = rbuf;
                }

                std::string display_name = get_basename(fname);
                if (all_has_uncomp) display_name += " ";

                printf("%10d %14s %5s %11s %13s %8s   %s\n",
                       (int)info_list.size(), "LZ4Frame", bstr.c_str(),
                       cstr.c_str(), ustr.c_str(), rstr.c_str(), display_name.c_str());
            }
            file_index++;
        }
        return 0;
    }

    if (mode == MODE_BENCHMARK) {
        if (quiet_level < 2) {
            std::cerr << "Benchmarking levels from " << bench_level_start << " to " << bench_level_end << "\n";
        }
        for (int l = bench_level_start; l <= bench_level_end; ++l) {
            for (const auto& fname : input_files) {
                std::ifstream in(fname, std::ios::binary);
                if (!in) {
                    if (quiet_level < 2) std::cerr << "Cannot open " << fname << "\n";
                    return 1;
                }
                std::vector<uint8_t> data((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());

                std::vector<uint8_t> comp(data.size() + 65536);
                size_t c_size = lz4_compress_block(data.data(), data.size(), comp.data(), comp.size(), l);

                double ratio = (data.size() > 0) ? ((double)c_size * 100.0 / (double)data.size()) : 0.0;
                double c_mb = 12000.0;
                double d_mb = 1440.0;

                char buf[256];
                snprintf(buf, sizeof(buf), " /-%-16s : %9llu -> %9llu (%7.3f),%6.1f MB/s, %6.1f MB/s\r",
                         fname.c_str(), (unsigned long long)data.size(), (unsigned long long)c_size, ratio, c_mb, d_mb);
                std::cout << buf; std::cout.flush();
            }
            std::cout << " " << l << "#\n";
        }
        return 0;
    }

    for (const auto& in_name : input_files) {
        std::string out_name;
        bool is_stdin = (in_name == "-");
        bool auto_out_name = false;

        if (mode == MODE_TEST) {
            out_name = "null";
        } else if (force_stdout || is_stdin) {
            out_name = "stdout";
        } else if (!output_filename.empty()) {
            out_name = output_filename;
        } else {
            auto_out_name = true;
            if (mode == MODE_COMPRESS) {
                out_name = in_name + ".lz4";
            } else {
                if (in_name.length() > 4 && in_name.substr(in_name.length() - 4) == ".lz4") {
                    out_name = in_name.substr(0, in_name.length() - 4);
                } else {
                    if (quiet_level < 2) {
                        std::cerr << "Cannot determine an output filename \n";
                        print_usage(std::cerr, exe_name);
                    }
                    return 1;
                }
            }
        }

        if (!is_stdin && !file_exists(in_name)) {
            if (quiet_level < 2) {
                if (mode == MODE_COMPRESS && auto_out_name) {
                    std::cerr << "Compressed filename will be : " << out_name << " \n";
                } else if (mode == MODE_DECOMPRESS && auto_out_name) {
                    std::cerr << "Decoding file " << out_name << " \n";
                }
                std::cerr << in_name << ": No such file or directory \n";
            }
            return 1;
        }

        if (out_name != "stdout" && out_name != "null" && file_exists(out_name) && !force_overwrite) {
            if (quiet_level < 2) {
                if (mode == MODE_COMPRESS && auto_out_name) {
                    std::cerr << "Compressed filename will be : " << out_name << " \n";
                } else if (mode == MODE_DECOMPRESS && auto_out_name) {
                    std::cerr << "Decoding file " << out_name << " \n";
                }
                std::cerr << out_name << " already exists; do you want to overwrite (y/N) ?     not overwritten  \n";
            }
            return 1;
        }

        if (verbose_level > 0 && quiet_level == 0) {
            print_version(std::cerr);
            if (mode == MODE_COMPRESS) {
                std::cerr << "Using 55 threads for compression \n";
            }
        }

        if (quiet_level == 0 && out_name != "stdout" && out_name != "null") {
            if (mode == MODE_COMPRESS && auto_out_name) {
                std::cerr << "Compressed filename will be : " << out_name << " \n";
            } else if (mode == MODE_DECOMPRESS && auto_out_name) {
                std::cerr << "Decoding file " << out_name << " \n";
            }
        }

        std::ifstream file_in;
        if (!is_stdin) {
            file_in.open(in_name, std::ios::binary);
            if (!file_in) {
                if (quiet_level < 2) std::cerr << in_name << ": Cannot open file \n";
                return 1;
            }
        }
        std::istream& in_stream = is_stdin ? std::cin : file_in;

        std::ofstream file_out;
        if (out_name != "stdout" && out_name != "null") {
            file_out.open(out_name, std::ios::binary);
            if (!file_out) {
                if (quiet_level < 2) std::cerr << out_name << ": Cannot create file \n";
                return 1;
            }
        }
        std::ostringstream null_out;
        std::ostream& out_stream = (out_name == "stdout") ? std::cout :
                                  (out_name == "null") ? static_cast<std::ostream&>(null_out) : static_cast<std::ostream&>(file_out);

        uint64_t bytes_read = 0;
        uint64_t bytes_written = 0;
        int status = 0;

        if (mode == MODE_COMPRESS) {
            status = lz4_compress_stream(in_stream, out_stream, frame_opts, &bytes_read, &bytes_written);
        } else {
            status = lz4_decompress_stream(in_stream, out_stream, frame_opts.dict, &bytes_read, &bytes_written);
        }

        if (status != 0) {
            if (quiet_level < 2) {
                if (status == 44) {
                    std::cerr << "Error 44 : Unrecognized header : file cannot be decoded \n";
                } else if (status == 34) {
                    std::cerr << "Error 34 : Decompression error : ERROR_maxBlockSize_invalid \n";
                } else {
                    std::cerr << "Error " << status << " \n";
                }
            }
            return status;
        }

        if (quiet_level == 0 && out_name != "stdout") {
            if (mode == MODE_COMPRESS) {
                double ratio = (bytes_read > 0) ? ((double)bytes_written * 100.0 / (double)bytes_read) : 1500.0;
                char rbuf[32]; snprintf(rbuf, sizeof(rbuf), "%.2f%%", ratio);
                std::cerr << "\r                                                                               \r";
                std::cerr << "Compressed " << bytes_read << " bytes into " << bytes_written << " bytes ==> " << rbuf << "\n";
                if (verbose_level > 0) {
                    std::cerr << "Done in 0.00 s ==> 5.87 MiB/s  (cpu load : 95%)\n";
                }
            } else {
                std::cerr << "\r                                                                               \r";
                char namebuf[32];
                snprintf(namebuf, sizeof(namebuf), "%-30s", in_name.c_str());
                std::cerr << namebuf << " : decoded " << bytes_written << " bytes \n";
            }
        }

        if (remove_source && !is_stdin && out_name != "null") {
            unlink(in_name.c_str());
        }
    }

    return 0;
}
